import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Array methods over single-statement loops","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/prefer-array-methods.md","filePath":"reference/rules/prefer-array-methods.md"}`),a={name:`reference/rules/prefer-array-methods.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="array-methods-over-single-statement-loops" tabindex="-1">Array methods over single-statement loops <a class="header-anchor" href="#array-methods-over-single-statement-loops" aria-label="Permalink to “Array methods over single-statement loops”">​</a></h1><p>A loop whose body is one statement, with no <code>break</code>, <code>continue</code>, <code>return</code> or <code>await</code>, can usually be written as an array method.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>The array method names the operation. <code>map</code> says a value comes back per element, <code>filter</code> says some are dropped, <code>forEach</code> says nothing is returned. A bare <code>for</code> says only that something repeats, and leaves the reader to work out which case applies.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p><code>forEach</code>, <code>map</code>, <code>filter</code>, <code>flatMap</code> or <code>reduce</code>, whichever names what the loop does.</p><h2 id="why-it-ships-as-a-warning" tabindex="-1">Why it ships as a warning <a class="header-anchor" href="#why-it-ships-as-a-warning" aria-label="Permalink to “Why it ships as a warning”">​</a></h2><p>The check is syntactic and cannot know what the loop iterates. A <code>Set</code>, a <code>Map</code> or a generator has no <code>map</code> or <code>filter</code>, so a single-statement loop over one can be flagged even though a direct rewrite is not possible. Convert with <code>[...iterable]</code> where that reads well, use the ignore marker where it does not, and raise the rule to <code>error</code> in config once your codebase&#39;s loops are mostly over arrays. If you run Biome&#39;s <code>noForEach</code> or a similar rule pointing the opposite way, keep only one of the two.</p><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to “Exceptions”">​</a></h2><p>This is not a ban on loops. Bodies with control flow are left alone, because they cannot be expressed as an array method. A hot path where a per-iteration closure allocation is a measured cost is a legitimate exception:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// vibator-ignore: hot path, runs per audio frame of a live call</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; index </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; index</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span></code></pre></div><p>The reason is required.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};